import { promises as fs } from \"node:fs\";
import path from \"node:path\";

const DATA_FILE = path.join(process.cwd(), \"data\", \"books.json\");

function normalizeStatus(status) {
  return status === \"finished\" ? \"finished\" : \"reading\";
}

function createId() {
  return "'`${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`;
}

async function ensureDataFile() {
  try {
    await fs.access(DATA_FILE);
  } catch {
    await fs.mkdir(path.dirname(DATA_FILE), { recursive: true });
    await fs.writeFile(DATA_FILE, "[]", "utf8");
  }
}

async function readBooks() {
  await ensureDataFile();
  const raw = await fs.readFile(DATA_FILE, "utf8");

  try {
    const parsed = JSON.parse(raw);

    if (!Array.isArray(parsed)) {
      return [];
    }

    return parsed
      .map((book) => ({
        id: String(book.id ?? ""),
        title: String(book.title ?? "").trim(),
        author: String(book.author ?? "").trim(),
        notes: String(book.notes ?? "").trim(),
        status: normalizeStatus(book.status),
        createdAt: Number(book.createdAt ?? Date.now()),
        finishedAt: book.finishedAt ? Number(book.finishedAt) : null,
      }))
      .filter((book) => book.id && book.title && book.author)
      .sort((a, b) => b.createdAt - a.createdAt);
  } catch {
    return [];
  }
}

async function writeBooks(books) {
  const json = JSON.stringify(books, null, 2);
  await fs.writeFile(DATA_FILE, `${json}'"\\n"'`, "utf8");
}

export async function getAllBooks() {
  return readBooks();
}

export async function getBookById(id) {
  const books = await readBooks();
  return books.find((book) => book.id === id) ?? null;
}

export async function addBook({ title, author, notes }) {
  const cleanTitle = String(title ?? "").trim();
  const cleanAuthor = String(author ?? "").trim();
  const cleanNotes = String(notes ?? "").trim();

  if (!cleanTitle || !cleanAuthor) {
    throw new Error("Title and author are required.");
  }

  const books = await readBooks();
  const createdAt = Date.now();

  const nextBook = {
    id: createId(),
    title: cleanTitle,
    author: cleanAuthor,
    notes: cleanNotes,
    status: "reading",
    createdAt,
    finishedAt: null,
  };

  books.push(nextBook);
  await writeBooks(books);

  return nextBook;
}

export async function markBookFinished(id) {
  const books = await readBooks();
  let found = false;

  const updated = books.map((book) => {
    if (book.id !== id) {
      return book;
    }

    found = true;

    if (book.status === "finished") {
      return book;
    }

    return {
      ...book,
      status: "finished",
      finishedAt: Date.now(),
    };
  });

  if (!found) {
    return false;
  }

  await writeBooks(updated);
  return true;
}
EOF

cat > /workspace/app/page.js <<'"'EOF'
import Link from \"next/link\";
import { revalidatePath } from \"next/cache\";
import { addBook, getAllBooks, markBookFinished } from \"@/lib/books\";

async function addBookAction(formData) {
  \"use server\";

  await addBook({
    title: formData.get(\"title\"),
    author: formData.get(\"author\"),
    notes: formData.get(\"notes\"),
  });

  revalidatePath(\"/\");
}

async function finishBookAction(formData) {
  \"use server\";

  const id = String(formData.get(\"id\") ?? \"\");

  if ("'!id) {
    return;
  }

  await markBookFinished(id);
  revalidatePath("/");
  revalidatePath(`/books/${id}`);
}

function BookList({ title, books, showFinishButton }) {
  return (
    <section className="panel stack">
      <h2>{title}</h2>

      {books.length === 0 ? (
        <p className="muted">No books here yet.</p>
      ) : (
        <ul className="list">
          {books.map((book) => (
            <li key={book.id} className="list-item">
              <div className="list-item-content">
                <h3>
                  <Link href={`/books/${book.id}`}>{book.title}</Link>
                </h3>
                <p>by {book.author}</p>
                <span className="badge">
                  {book.status === "finished" ? "Finished" : "Currently reading"}
                </span>
              </div>

              {showFinishButton ? (
                <form action={finishBookAction}>
                  <input type="hidden" name="id" value={book.id} />
                  <button type="submit" className="secondary">
                    Mark finished
                  </button>
                </form>
              ) : null}
            </li>
          ))}
        </ul>
      )}
    </section>
  );
}

export default async function HomePage() {
  const books = await getAllBooks();
  const reading = books.filter((book) => book.status === "reading");
  const finished = books.filter((book) => book.status === "finished");

  return (
    <main className="stack">
      <header className="panel stack">
        <h1>Reading Tracker</h1>
        <p className="muted">
          Keep a simple list of what you are reading and finished.
        </p>
      </header>

      <section className="panel stack">
        <h2>Add a book</h2>
        <form action={addBookAction}>
          <label htmlFor="title">
            Title
            <input id="title" name="title" required />
          </label>

          <label htmlFor="author">
            Author
            <input id="author" name="author" required />
          </label>

          <label htmlFor="notes">
            Notes
            <textarea
              id="notes"
              name="notes"
              placeholder="Anything you want to remember about this book"
            />
          </label>

          <div>
            <button type="submit">Add book</button>
          </div>
        </form>
      </section>

      <div className="section-grid">
        <BookList
          title="Currently reading"
          books={reading}
          showFinishButton={true}
        />
        <BookList title="Finished" books={finished} showFinishButton={false} />
      </div>
    </main>
  );
}
EOF

