import { promises as fs } from \"node:fs\";
import path from \"node:path\";

const DATA_FILE = path.join(process.cwd(), \"data\", \"books.json\");

function normalizeStatus(status) {
  return status === \"finished\" ? \"finished\" : \"reading\";
}

function createId() {
  return "'`${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`;
}

async function ensureDataFile() {
  try {
    await fs.access(DATA_FILE);
  } catch {
    await fs.mkdir(path.dirname(DATA_FILE), { recursive: true });
    await fs.writeFile(DATA_FILE, "[]", "utf8");
  }
}

async function readBooks() {
  await ensureDataFile();
  const raw = await fs.readFile(DATA_FILE, "utf8");

  try {
    const parsed = JSON.parse(raw);

    if (!Array.isArray(parsed)) {
      return [];
    }

    return parsed
      .map((book) => ({
        id: String(book.id ?? ""),
        title: String(book.title ?? "").trim(),
        author: String(book.author ?? "").trim(),
        notes: String(book.notes ?? "").trim(),
        status: normalizeStatus(book.status),
        createdAt: Number(book.createdAt ?? Date.now()),
        finishedAt: book.finishedAt ? Number(book.finishedAt) : null,
      }))
      .filter((book) => book.id && book.title && book.author)
      .sort((a, b) => b.createdAt - a.createdAt);
  } catch {
    return [];
  }
}

async function writeBooks(books) {
  const json = JSON.stringify(books, null, 2);
  await fs.writeFile(DATA_FILE, `${json}'"\\n"'`, "utf8");
}

export async function getAllBooks() {
  return readBooks();
}

export async function getBookById(id) {
  const books = await readBooks();
  return books.find((book) => book.id === id) ?? null;
}

export async function addBook({ title, author, notes }) {
  const cleanTitle = String(title ?? "").trim();
  const cleanAuthor = String(author ?? "").trim();
  const cleanNotes = String(notes ?? "").trim();

  if (!cleanTitle || !cleanAuthor) {
    throw new Error("Title and author are required.");
  }

  const books = await readBooks();
  const createdAt = Date.now();

  const nextBook = {
    id: createId(),
    title: cleanTitle,
    author: cleanAuthor,
    notes: cleanNotes,
    status: "reading",
    createdAt,
    finishedAt: null,
  };

  books.push(nextBook);
  await writeBooks(books);

  return nextBook;
}

export async function markBookFinished(id) {
  const books = await readBooks();
  let found = false;

  const updated = books.map((book) => {
    if (book.id !== id) {
      return book;
    }

    found = true;

    if (book.status === "finished") {
      return book;
    }

    return {
      ...book,
      status: "finished",
      finishedAt: Date.now(),
    };
  });

  if (!found) {
    return false;
  }

  await writeBooks(updated);
  return true;
}
