            />
          </label>

          <div>
            <button type="submit">Add book</button>
          </div>
        </form>
      </section>

      <div className="section-grid">
        <BookList
          title="Currently reading"
          books={reading}
          showFinishButton={true}
        />
        <BookList title="Finished" books={finished} showFinishButton={false} />
      </div>
    </main>
  );
}
