      </header>

      <section className="panel stack">
        <h2>Notes</h2>
        {book.notes ? (
          <p style={{ whiteSpace: "pre-wrap" }}>{book.notes}</p>
        ) : (
          <p className="muted">No notes yet.</p>
        )}
      </section>

      <section className="panel stack">
        <h2>Share this book</h2>
        <p className="muted">
          Share this page URL directly. Anyone with the link can view this book.
        </p>
      </section>
    </main>
  );
}
